import { motion, MotionConfig } from "motion/react"

export default function App() {
  return (
    // "user" follows prefers-reduced-motion instead of animating regardless
    <MotionConfig reducedMotion="user">
      <motion.div
        initial={{ opacity: 0, y: 12 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.4, ease: "easeOut" }}
        style={{ padding: 16, borderRadius: 8, background: "#1b1b1f", color: "#f5f5f5" }}
      >
        Motion is ready
      </motion.div>
    </MotionConfig>
  )
}

