import { motion } from "motion/react"

const list = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: { staggerChildren: 0.08, delayChildren: 0.1 },
  },
}

const item = {
  hidden: { opacity: 0, y: 8 },
  visible: { opacity: 1, y: 0 },
}

export default function InboxList() {
  return (
    <motion.ul initial="hidden" animate="visible" variants={list}>
      {["Inbox", "Drafts", "Sent"].map((name) => (
        <motion.li key={name} variants={item}>
          {name}
        </motion.li>
      ))}
    </motion.ul>
  )
}

// Variant functions receive `custom`, so each row staggers by its own index
const row = {
  hidden: (index: number) => ({ opacity: 0, x: -12 * index }),
  visible: (index: number) => ({ opacity: 1, x: 0, transition: { delay: index * 0.05 } }),
}

export function Row() {
  return <motion.li custom={2} variants={row} initial="hidden" animate="visible" />
}

