import { AnimatePresence, motion } from "motion/react"

export default function Toast({ visible }) {
  return (
    // mode "wait" finishes the exit before the next child enters
    <AnimatePresence mode="wait">
      {visible && (
        <motion.div
          key="toast"
          initial={{ opacity: 0, y: 16 }}
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0, y: 16 }}
          transition={{ duration: 0.2 }}
          style={{ padding: 12, borderRadius: 8, background: "#FFF312", color: "#111" }}
        >
          Saved
        </motion.div>
      )}
    </AnimatePresence>
  )
}

// "popLayout" pulls the item out of flow at once so its siblings close the gap
<AnimatePresence mode="popLayout" initial={false}>
  {items.map((item) => (
